package org.example.server.workflow; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/workflow") public class WorkflowController { private final WorkflowService s; public WorkflowController(WorkflowService s){this.s=s;} @GetMapping public List<WorkflowDtos.Document> list(@RequestParam String type){return s.list(type);} @GetMapping("/{id}") public WorkflowDtos.Document get(@PathVariable int id){return s.get(id);} @PostMapping public WorkflowDtos.Document save(@RequestBody WorkflowDtos.Document d){return s.save(d);} @PutMapping public WorkflowDtos.Document update(@RequestBody WorkflowDtos.Document d){return s.save(d);} @DeleteMapping("/{id}") public Map<String,Object> delete(@PathVariable int id,@RequestParam long rowVersion){s.delete(id,rowVersion);return Map.of("success",true);} @GetMapping("/next-number") public WorkflowDtos.NextNumber next(@RequestParam String type){return new WorkflowDtos.NextNumber(s.next(type));} @GetMapping("/stock-availability") public WorkflowDtos.StockAvailability stockAvailability(@RequestParam String itemCode,@RequestParam(required=false) Integer documentId){return s.stockAvailability(itemCode,documentId);} @GetMapping("/project-profitability") public WorkflowDtos.ProjectProfitability profitability(@RequestParam String projectNo){return s.profitability(projectNo);}}
